<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import type {NormalizedAnalysis,PeakField} from '../peakRecordTypes';
import {FIELD_LABELS,quantityText,definitionLabel} from '../peakRecordAdapters';
import {clonePeak} from '../peakResultImportState';
const props=defineProps<{analysis:NormalizedAnalysis}>();
const emit=defineEmits<{revised:[analysis:NormalizedAnalysis]}>();
const page=ref(0),search=ref(''),selected=ref('');
const reviewScope=ref<'all'|'current'>('all'),reviewConfirmed=ref(false),reviewNote=ref('');
const reviewFields=ref<Record<PeakField,{unit:string;definition:string}>>({position:{unit:'',definition:''},width:{unit:'',definition:''},height:{unit:'',definition:''},area:{unit:'',definition:''}});
const definitions={position:['two_theta','apex','model_position','centroid'],width:['fwhm'],height:['height'],area:['total','range']};
const fields:PeakField[]=['position','width','height','area'];
const filtered=computed(()=>props.analysis.records.filter(r=>[r.sample_id,r.peak_id,r.label,r.source.filename].join(' ').toLowerCase().includes(search.value.toLowerCase())));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/50)));
const rows=computed(()=>filtered.value.slice(page.value*50,(page.value+1)*50));
const detail=computed(()=>props.analysis.records.find(r=>r.id===selected.value));
watch([()=>props.analysis,search],()=>{page.value=0;selected.value='';});
function applyReview(){if(!reviewConfirmed.value)return;const a=clonePeak(props.analysis);for(const r of a.records){if(reviewScope.value==='current'&&r.id!==selected.value)continue;const changes:Record<string,unknown>={};for(const f of fields){const entry=reviewFields.value[f],q=r.fields[f];if(!entry.unit.trim()&&!entry.definition)continue;changes[f]={before:{unit:q.unit,definition:q.definition},after:{unit:entry.unit.trim()||q.unit,definition:entry.definition||q.definition}};if(entry.unit.trim())q.unit=entry.unit.trim();if(entry.definition)q.definition=entry.definition;}
 if(Object.keys(changes).length){r.metadata??={};const old=Array.isArray(r.metadata.quantity_reviews)?r.metadata.quantity_reviews:[];r.metadata.quantity_reviews=[...old,{version:1,at:new Date().toISOString(),kind:'user_declared_no_numeric_conversion',note:reviewNote.value,changes}];}}
 reviewConfirmed.value=false;emit('revised',a);}
</script>
<template>
 <section class="peak-records" aria-label="标准峰参数">
  <div class="peak-section-heading"><div><h3>标准峰参数</h3><p class="hint">{{analysis.records.length}} 条峰记录；原值、数量定义和来源保留。解析成功不表示拟合质量已验证。</p></div><label>查找样品／峰／文件<input v-model="search" type="search" /></label></div>
  <details class="peak-detail"><summary>核对字段定义与单位</summary><p class="hint">用于补充内部拟合或源文件未声明的单位。以下操作声明当前数值的含义，不进行数值换算；已有原值和文件来源保留，修改会使旧二次计算失效。无法解析的空数值须回到导入映射重新处理。</p><label>应用范围<select v-model="reviewScope"><option value="all">全部 {{analysis.records.length}} 峰</option><option value="current" :disabled="!selected">当前展开的峰</option></select></label><div class="peak-table-scroll"><table><thead><tr><th>字段</th><th>当前数值的单位（留空不改）</th><th>数量定义（留空不改）</th></tr></thead><tbody><tr v-for="f in fields" :key="f"><th>{{FIELD_LABELS[f]}}</th><td><input v-model="reviewFields[f].unit" :data-test="`review-unit-${f}`" :aria-label="`${FIELD_LABELS[f]}声明单位`" /></td><td><select v-model="reviewFields[f].definition" :aria-label="`${FIELD_LABELS[f]}声明定义`"><option value="">保持原定义</option><option v-for="d in definitions[f]" :key="d" :value="d">{{definitionLabel(d)}}</option></select></td></tr></tbody></table></div><label>声明依据<input v-model="reviewNote" placeholder="如原始仪器报告的轴单位／积分口径" /></label><label class="peak-checkbox"><input v-model="reviewConfirmed" type="checkbox" data-test="review-confirm" />我已核对当前数值与声明单位相符；不需要数值换算</label><button :disabled="!reviewConfirmed||reviewScope==='current'&&!selected" data-test="apply-quantity-review" @click="applyReview">应用单位与定义声明</button></details>
  <div class="peak-table-scroll" tabindex="0" role="region" aria-label="峰参数表"><table><thead><tr><th>样品 / 峰</th><th v-for="f in fields" :key="f">{{FIELD_LABELS[f]}}</th><th>来源</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><th><button class="quiet-button" @click="selected=selected===r.id?'':r.id" :aria-expanded="selected===r.id">{{r.sample_id}} · {{r.peak_id}}</button><small>{{r.label}} · {{r.model||'模型未知'}}</small><small>{{r.status==='invalid'?'字段异常':r.status==='review'?'待复核':'已解析'}}</small></th><td v-for="f in fields" :key="f"><strong>{{quantityText(r.fields[f])}}</strong><small>{{definitionLabel(r.fields[f].definition)}}</small><small v-if="r.fields[f].standard_error!=null">标准误 {{r.fields[f].standard_error}}</small><small v-else>标准误未提供</small><small v-if="r.fields[f].reason">{{r.fields[f].reason}}</small></td><td>{{r.source.filename}}<small>{{r.source.sheet}} · 第 {{r.source.row}} 行</small></td></tr><tr v-if="!rows.length"><td colspan="6">暂无匹配的峰记录。</td></tr></tbody></table></div>
  <div class="peak-pagination"><button :disabled="page===0" @click="page--">上一页</button><span>第 {{page+1}} / {{pages}} 页 · 每页 50 峰</span><button :disabled="page+1>=pages" @click="page++">下一页</button></div>
  <details v-if="detail" open class="peak-detail"><summary>{{detail.peak_id}} · 数值与来源</summary><dl><template v-for="f in fields" :key="f"><dt>{{FIELD_LABELS[f]}}</dt><dd>原值 {{detail.fields[f].raw_value??'未提供'}} · 原定义 {{detail.fields[f].raw_definition??'未提供'}} · 列 {{detail.fields[f].source_column??'未提供'}} · {{detail.fields[f].reason??'按已确认口径解析'}}</dd></template></dl><p class="hint">来源 SHA-256：{{detail.source.file_sha256}}</p><details><summary>完整来源和字段记录</summary><pre>{{JSON.stringify(detail,null,2)}}</pre></details></details>
  <details class="peak-detail"><summary>谱级拟合误差与质量（{{analysis.spectra.length}} 谱）</summary><p class="hint">下列指标按源文件或内部拟合结果提供，不根据解析成功推断收敛；参数标准误与整体拟合误差分别记录。</p><div class="peak-table-scroll"><table><thead><tr><th>样品 / 谱</th><th>指标</th><th>值</th><th>来源 / 缺失原因</th></tr></thead><tbody><template v-for="s in analysis.spectra" :key="s.id"><tr v-if="!Object.keys(s.metrics).length"><th>{{s.sample_id}} / {{s.id}}</th><td colspan="3">未提供拟合误差或质量指标</td></tr><tr v-for="(m,name) in s.metrics" :key="name"><th>{{s.sample_id}}</th><td>{{name}}</td><td>{{m.value??'未提供'}} {{m.unit}}</td><td>{{m.reason??`${m.source_row??'—'} 行 / ${m.source_column??'—'}`}}</td></tr></template><tr v-if="!analysis.spectra.length"><td colspan="4">未提供谱级质量指标。</td></tr></tbody></table></div></details>
 </section>
</template>
